+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.85rem;
+    }
+
+    input[type="checkbox"] {
+      margin: 0.15rem 0 0;
+      inline-size: 1.2rem;
+      block-size: 1.2rem;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    label {
+      font-size: 1rem;
+      line-height: 1.5;
+      font-weight: 600;
+    }
+
+    .required-indicator {
+      color: var(--error);
+      font-weight: 700;
+    }
+
+    .helper-text,
+    .error-text,
+    .status-message {
+      margin: 0;
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      color: var(--text-muted);
+    }
+
+    .error-text {
+      color: var(--error);
+      font-weight: 600;
+    }
+
+    .status-message {
+      min-height: 1.5rem;
+      color: var(--text-main);
+      font-weight: 600;
+    }
+
+    .actions {
+      display: flex;
+      justify-content: flex-start;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 0.95rem 1.4rem;
+      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
+      color: #fff;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+      box-shadow: 0 14px 24px rgba(37, 99, 235, 0.25);
+    }
+
+    a {
+      color: inherit;
+    }
+
+    button:hover {
+      filter: brightness(1.03);
+    }
+
+    a:focus-visible,
+    input:focus-visible,
+    button:focus-visible {
+      outline: 3px solid #0f172a;
+      outline-offset: 3px;
+    }
+
+    .form-field[data-invalid="true"] {
+      border-color: rgba(180, 35, 24, 0.45);
+      background: rgba(254, 242, 242, 0.96);
+    }
+
+    @media (max-width: 30rem) {
+      .card {
+        border-radius: 1.25rem;
+      }
+
+      .actions,
+      button {
+        width: 100%;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button {
+        border: 1px solid CanvasText;
+        box-shadow: none;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content">
+    <section class="card" aria-labelledby="page-title">
+      <p class="eyebrow">Quick setup</p>
+      <h1 id="page-title">Confirm your consent</h1>
+      <p class="intro">Review the final step below to continue with your product access.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field" data-invalid="false">
+          <div class="checkbox-row">
+            <input
+              id="consent"
+              name="consent"
+              type="checkbox"
+              required
+              aria-describedby="consent-help"
+            >
+            <label for="consent">
+              I agree to the Terms of Use <span class="required-indicator" aria-hidden="true">*</span>
+            </label>
+          </div>
+          <p id="consent-help" class="helper-text">Required to finish setup and continue.</p>
+          <p id="consent-error" class="error-text" hidden>Error: Please agree to the Terms of Use to continue.</p>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Continue</button>
+        </div>
+
+        <p id="form-status" class="status-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById("consent-form");
+    const checkbox = document.getElementById("consent");
+    const field = checkbox.closest(".form-field");
+    const errorMessage = document.getElementById("consent-error");
+    const statusMessage = document.getElementById("form-status");
+
+    function showError() {
+      field.dataset.invalid = "true";
+      checkbox.setAttribute("aria-invalid", "true");
+      checkbox.setAttribute("aria-describedby", "consent-help consent-error");
+      errorMessage.hidden = false;
+    }
+
+    function clearError() {
+      field.dataset.invalid = "false";
+      checkbox.removeAttribute("aria-invalid");
+      checkbox.setAttribute("aria-describedby", "consent-help");
+      errorMessage.hidden = true;
+    }
+
+    checkbox.addEventListener("change", () => {
+      if (checkbox.checked) {
+        clearError();
+        statusMessage.textContent = "";
+      }
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        showError();
+        statusMessage.textContent = "Please review the required consent checkbox.";
+        checkbox.focus();
+        return;
+      }
+
+      clearError();
+      statusMessage.textContent = "Consent recorded. You're ready to continue.";
+    });
+  </script>
+</body>
+</html>
*** End Patch
