<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Consent form</title>
  <style>
    :root {
      color-scheme: light;
      --page-bg: #f3f6fb;
      --card-bg: rgba(255, 255, 255, 0.92);
      --card-border: rgba(15, 23, 42, 0.08);
      --text-main: #0f172a;
      --text-muted: #475569;
      --accent: #2563eb;
      --accent-dark: #1d4ed8;
      --error: #b42318;
      --shadow: 0 24px 50px rgba(15, 23, 42, 0.14);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.18), transparent 32%),
        linear-gradient(180deg, #f8fbff 0%, var(--page-bg) 100%);
      color: var(--text-main);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: -3rem;
      padding: 0.75rem 1rem;
      background: var(--text-main);
      color: #fff;
      border-radius: 0.75rem;
      z-index: 1000;
      text-decoration: none;
    }

    .skip-link:focus {
      top: 1rem;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 1.5rem;
    }

    .card {
      width: min(100%, 30rem);
      padding: clamp(1.5rem, 4vw, 2.5rem);
      background: var(--card-bg);
      border: 1px solid var(--card-border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.9rem, 4vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0.9rem 0 1.75rem;
      color: var(--text-muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.6rem;
      padding: 1rem;
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: 1rem;
      background: rgba(248, 250, 252, 0.88);
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.85rem;
    }

    input[type="checkbox"] {
      margin: 0.15rem 0 0;
      inline-size: 1.2rem;
      block-size: 1.2rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    label {
      font-size: 1rem;
      line-height: 1.5;
      font-weight: 600;
    }

    .required-indicator {
      color: var(--error);
      font-weight: 700;
    }

    .helper-text,
    .error-text,
    .status-message {
      margin: 0;
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--text-muted);
    }

    .error-text {
      color: var(--error);
      font-weight: 600;
    }

    .status-message {
      min-height: 1.5rem;
      color: var(--text-main);
      font-weight: 600;
    }

    .actions {
      display: flex;
      justify-content: flex-start;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 14px 24px rgba(37, 99, 235, 0.25);
    }

    a {
      color: inherit;
    }

    button:hover {
      filter: brightness(1.03);
    }

    a:focus-visible,
    input:focus-visible,
    button:focus-visible {
      outline: 3px solid #0f172a;
      outline-offset: 3px;
    }

    .form-field[data-invalid="true"] {
      border-color: rgba(180, 35, 24, 0.45);
      background: rgba(254, 242, 242, 0.96);
    }

    @media (max-width: 30rem) {
      .card {
        border-radius: 1.25rem;
      }

      .actions,
      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      button {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      button {
        background: ButtonFace;
        color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Quick setup</p>
      <h1 id="page-title">Confirm your consent</h1>
      <p class="intro">Review the final step below to continue with your product access.</p>

      <form id="consent-form" novalidate>
        <div class="form-field" data-invalid="false">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="consent-help"
            >
            <label for="consent">
              I agree to the Terms of Use <span class="required-indicator" aria-hidden="true">*</span>
            </label>
          </div>
          <p id="consent-help" class="helper-text">Required to finish setup and continue.</p>
          <p id="consent-error" class="error-text" hidden>Error: Please agree to the Terms of Use to continue.</p>
        </div>

        <div class="actions">
          <button type="submit">Continue</button>
        </div>

        <p id="form-status" class="status-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("consent");
    const field = checkbox.closest(".form-field");
    const errorMessage = document.getElementById("consent-error");
    const statusMessage = document.getElementById("form-status");

    function showError() {
      field.dataset.invalid = "true";
      checkbox.setAttribute("aria-invalid", "true");
      checkbox.setAttribute("aria-describedby", "consent-help consent-error");
      errorMessage.hidden = false;
    }

    function clearError() {
      field.dataset.invalid = "false";
      checkbox.removeAttribute("aria-invalid");
      checkbox.setAttribute("aria-describedby", "consent-help");
      errorMessage.hidden = true;
    }

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        clearError();
        statusMessage.textContent = "";
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        showError();
        statusMessage.textContent = "Please review the required consent checkbox.";
        checkbox.focus();
        return;
      }

      clearError();
      statusMessage.textContent = "Consent recorded. You're ready to continue.";
    });
  </script>
</body>
</html>
